      B: "Amazon Bedrock ガードレールを設定し、コンテンツフィルター（プロンプト攻撃フィルターを含む）を使用してプロンプトインジェクション攻撃から保護します。コンテンツフィルターを「高」に設定します。AWS WAF を使用して不審な入力をブロックします。AWS CloudTrail を使用して監査用の API コールをログに記録します。",
