      D: "Amazon Bedrock ガードレールを設定し、コンテンツフィルターを使用して有害なコンテンツから保護します。コンテンツフィルターを「高」に設定します。単語フィルターを使用して既知の攻撃パターンから保護します。クロスリージョンのガードレールレプリケーションを設定して、フェイルオーバー機能を提供します。コンプライアンス監査のために AWS CloudTrail にログを保存します。"
