      D: "Amazon Bedrock Flows でカスタムプロンプト評価フローを作成し、同じ臨床文書の入力を異なるプロンプトバリアントに適用します。Amazon Comprehend Medical を使用して、各バージョンの事実の正確性を分析し、スコアリングします。"
