    answer: "D",
    explanation:
      "正解は D。要件は『生成出力の完全な追跡可能性』『データソースの登録とメタデータタギングによる出典帰属』『パイプライン全体のデータアクセス・使用状況の監査ログ』。D は AWS Glue データカタログで全データソースを登録、メタデータタグで出典帰属、CloudTrail でサービス横断のアクセスとアクティビティをログ記録する。登録・タギング・横断監査の 3 点を満たす。\n\n・A が誤り: Lake Formation はアクセス制御が主眼で、データソース『登録』と出典帰属のタギングの包括性では Glue データカタログに劣り、CloudTrail だけだと帰属メタデータの仕組みが弱い。\n・B が誤り: 監視が CloudWatch Logs 中心で、サービス横断のアクセス監査証跡（CloudTrail 相当）が不足。\n・C が誤り: S3 オブジェクトタギング中心で、全データソースの体系的な登録とパイプライン全体の監査が D ほど網羅的でない。",
