    explanation:
      "正解は A と B と D。要件は『ドキュメントから構造化データ抽出』『推論前に PII 編集』『FM で承認生成』『低信頼度の抽出を同一リージョンの人間レビューへ』『リージョンごとのデータレジデンシーと監査可能性』『日次 25,000 件・99.9% 可用性』。A は Textract＋A2I を同一リージョンに置き抽出し低信頼度ページを人間レビューへ。B は Lambda で推論前 PII 編集＋ガードレール＋リージョン別 IAM でレジデンシー強制。D は S3 にメタデータ付きで保存し IAM でリージョン内保存を強制、タグで監査可能に。\n\n・C が誤り: Kendra/OpenSearch でフィールド値をセマンティック抽出するのは本問の構造化抽出＋人間レビューの要件に対し的外れ。\n・E が誤り: Glue Data Quality 検証は本問の必須要件（PII 編集・人間レビュー・レジデンシー）に直結せず、プロンプト最適化中心で焦点がずれる。\n・F が誤り: SageMaker Clarify の公平性/バイアスレポートは本問が求める機能ではない。",
