      D: "同じ意味を持つ標準化された多言語テスト会話を設定します。Amazon Bedrock のモデル評価ジョブを使用して、テスト会話を並行して実行します。類似性とハルシネーションのしきい値を適用します。プロセスを CI/CD パイプラインに統合して、失敗したリリースをブロックします。"
