      D: "Amazon API Gateway REST API を、Amazon Bedrock を呼び出す AWS Lambda 関数と統合します。Lambda レスポンスストリーミングを使用してレスポンスをストリーミングします。Lambda 関数内でトークン制限を適用します。Lambda 関数内で再試行ロジックを実装し、Lambda と API Gateway のタイムアウトは上限として適切に設定します。"
