      E: "Amazon Bedrock のモデル呼び出しイベントをキャプチャするために Amazon EventBridge ルールを実装します。トークン使用量データを、Amazon OpenSearch Serverless をターゲットとする Amazon Data Firehose 配信ストリームにルーティングします。OpenSearch ダッシュボードを使用して使用パターンを分析します。"
