      C: "VPC エンドポイントポリシーを使用してサービスへのアクセスを制限します。AWS Config を使用して、リソースの変更とセキュリティルールへの準拠を追跡します。保管中のデータを暗号化するために、AWS KMS キーによるサーバー側の暗号化 (SSE-KMS) を使用します。モデルの I/O を別々の Amazon S3 バケットに保存します。ファイルレベルのインタラクションを追跡するために、S3 サーバーアクセスログを有効にします。",
