      B: "Amazon API Gateway REST API を AWS Lambda 統合で設定します。REST API が Amazon Bedrock の標準的な InvokeModel API を呼び出し、フロントエンドのクライアント側で 100 ミリ秒ごとに完全な応答チャンクをポーリングするように実装します。",
      C: "中間ゲートウェイやプロキシレイヤーなしで、IAM ユーザー認証情報と InvokeModelWithResponseStream API を使用して、Amazon Bedrock への直接的なフロントエンドクライアント接続を実装します。",
      D: "Amazon API Gateway HTTP API を AWS Lambda 統合で設定します。HTTP API が完全な応答を Amazon DynamoDB テーブルにキャッシュし、フロントエンドクライアントに複数のページ分割された GET リクエストを介して応答を提供するように設定します。"
