      C: "推論と会話管理に Amazon Bedrock Agents を使用します。オーケストレーションに AWS Step Functions と Amazon SQS キューを使用します。ステップ間のメモリを維持するために、エージェントの状態を Amazon DynamoDB に保存します。",
