      "正解は B と C。要件は『長い技術文書の要約でのハルシネーション急増を削減』『事実正確性の目標達成』『1 時間 1,000 件以上を各 3 秒以内』。B はナレッジベースで RAG を使い、セマンティックチャンキングとチューニング済み埋め込みで要約をソースに根拠づけ、ハルシネーションを根本的に減らす。C は Bedrock ガードレールでハルシネーション関連パターンに一致する出力をブロックし、安全網として事実性を担保する。RAG＋ガードレールの二段構えが有効。\n\n・A が誤り: CoT の段階推論はハルシネーションを必ずしも減らさず、各ステップで推論を増やすとレイテンシー（3 秒以内）を圧迫しスループットにも不利。\n・D が誤り: temperature を上げると出力のランダム性が増し、ハルシネーションはむしろ悪化する（下げるべき）。\n・E が誤り: 文書全体を一度に要約させる現行方式こそがハルシネーションの原因で、改善策にならない。",
