      D: "Amazon DynamoDB を使用して、正規化されたクエリテキストにグローバルセカンダリインデックスを作成することで、キャッシュソリューションを作成します。受信クエリにステミングを適用します。キャッシュされた顧客クエリのインデックスをクエリします。"
