      C: "1 つの AWS CDK アプリケーションを作成します。アプリケーションが `aws_bedrock.FoundationModel.fromFoundationModelId()` メソッドを使用して Amazon Bedrock FM を呼び出すように設定します。AWS CodeBuild のデプロイアクションを使用する各環境用のデプロイステージを持つパイプラインを AWS CodePipeline で作成します。",
      D: "本番環境用に 1 つの AWS CDK アプリケーションを作成します。アプリケーションが `aws_bedrock.ProvisionedModel.fromProvisionedModelArn()` メソッドを使用して Amazon Bedrock FM を呼び出すように設定します。AWS CodePipeline でパイプラインを作成します。AWS CodeBuild のデプロイアクションを使用して本番環境にデプロイするようにパイプラインを設定します。開発環境については、本番アプリケーションのコードを参照して手動でリソースを再作成します。"
