      "ある企業が、Amazon Bedrock の基盤モデル (FM) を使用する生成 AI (GenAI) アプリケーションを開発しています。このアプリケーションには、いくつかのカスタムツール統合があります。このアプリケーションは、ユーザートラフィックが一定であるにもかかわらず、予期しないトークン消費の急増を経験しています。\n\nこの企業は、Amazon Bedrock のモデル呼び出しロギングを使用して InputTokenCount メトリクスと OutputTokenCount メトリクスをモニタリングするソリューションを必要としています。このソリューションは、ツール使用における異常なパターンを検出し、どの特定のツール統合が異常なトークン消費を引き起こしているかを特定する必要があります。また、このソリューションは、トラフィックパターンの変化に応じてしきい値を自動的に調整する必要があります。\n\nどのソリューションがこれらの要件を満たしますか？",
