      B: "エージェントと特典 Lambda 関数を実行する 4 つのタスクを持つ AWS Step Functions ステートマシンを作成します。各タスクステップにリトライとキャッチのブランチを設定します。",
      C: "各エージェントに個別のリトライ / フォールバックメカニズムを設定します。エージェントと特典 Lambda 関数への呼び出しをオーケストレーションするために、2 番目の Lambda 関数を作成します。2 番目の Lambda 関数の背後に Amazon API Gateway REST API を定義します。",
      D: "エージェントと特典 Lambda 関数への呼び出しをオーケストレーションするために、2 番目の Lambda 関数を作成します。2 番目の Lambda 関数を実行する 1 つのタスクを持つ AWS Step Functions ステートマシンを作成します。タスクステップにリトライとキャッチのブランチを設定します。"
