      C: "Amazon CloudWatch を使用してレイテンシーとエラーレートを監視します。ソースを引用するために、モデルプロンプトをアプリケーションバックエンドに直接埋め込みます。監査のために、ユーザーとのアプリケーションのやり取りを Amazon RDS に保存します。",
