      B: "アクティブなモデルプロバイダーを AWS AppConfig に保存します。Lambda 関数が実行時に設定を読み取り、呼び出すモデルを決定するように設定します。",
      C: "Amazon API Gateway REST API を設定して、リクエストを個別の Lambda 関数にルーティングします。各 Lambda 関数を特定のモデルプロバイダーにハードコーディングします。統合ターゲットを手動で切り替えます。",
      D: "アクティブなモデルプロバイダーを Amazon S3 でホストされている JSON ファイルに保存します。AWS AppConfig を使用して、S3 ファイルをホストされた設定ソースとして参照します。Lambda 関数が実行時に AppConfig を介してファイルを読み取り、呼び出すモデルを決定するように設定します。"
