    explanation:
      "正解は B。要件は『判例文書を検索して応答を補強』『法的概念・特定の法律用語・引用の間の意味的関係を特定』『高速かつ正確』。B は OpenSearch Service でベクトル検索（意味的関係）とキーワード検索（特定用語・引用の正確一致）を組み合わせたハイブリッド検索をデプロイし、Bedrock のリランカーモデルで結果の関連性を最適化する。意味理解と正確一致の両立＋リランクで、法務検索の精度と速度を満たす。\n\n・A が誤り: デフォルトのベクトル検索設定＋クエリ拡張だけでは、特定の法律用語や引用の正確一致と意味的関係の両立が弱い。\n・C が誤り: Kendra のクエリ提案＋後処理は、ベクトル/キーワードを統合した高精度検索とリランクの枠組みに劣る。\n・D が誤り: ベクトル検索＋RDS のキーワードフィルタを Lambda でマージする自作構成は、OpenSearch のハイブリッド検索＋Bedrock リランカーを使う B より複雑で最適化も難しい。",
