    answer: "D",
    explanation:
      "正解は D。要件は『Bedrock Knowledge Bases の RAG(RetrieveAndGenerateStream)』『初回検索で意味は似るが文脈的に無関係な文書が返り、ハルシネーションや不正確な規制ガイダンスが発生』『より関連性の高い文書を返すよう改善』『運用オーバーヘッド最小』。D はナレッジベースの再ランク付け設定を通じて Bedrock の reranker モデルを使い、文書の関連性スコアリングを改善して文脈評価に基づき結果を並べ替える。ナレッジベースにネイティブ統合された再ランク設定なので、追加インフラ無しで最小運用で関連性を高められる。\n\n・A が誤り: SageMaker エンドポイントで自前のランキングモデルを運用＋API Gateway 連携は運用オーバーヘッドが大きい。\n・B が誤り: Comprehend 分類＋Textract＋Neptune のグラフ計算という寄せ集めは複雑で、再ランク付けの最小構成として不適。\n・C が誤り: Retrieve→Rerank API→InvokeModelWithResponseStream を自前パイプラインで組むのは、ナレッジベースの再ランク設定を使う D に比べ実装・運用が重い。",
